\textbf{\textcolor{red}{EXAMPLE 5 --- Local Linear Trend (LLT).}}

Basically a random walk with drift where the drift itself changes (the slope is its own random walk).

\begin{keydef}
\textbf{Local Linear Trend (LLT) DLM.}

\emph{State} $\theta_t = (\mu_t,\, \beta_t)^\top \in \mathbb{R}^2$ (level $\mu_t$, slope $\beta_t$).

\emph{State equations.}
\[ \mu_t = \mu_{t-1} + \beta_{t-1} + w_{1,t}, \qquad w_{1,t} \overset{\text{iid}}{\sim} \mathcal{N}(0,\, \sigma_{w_1}^2); \]
\[ \beta_t = \beta_{t-1} + w_{2,t}, \qquad w_{2,t} \overset{\text{iid}}{\sim} \mathcal{N}(0,\, \sigma_{w_2}^2). \]
In matrix form:
\[ \theta_t \;=\; \underbrace{\begin{pmatrix}1 & 1 \\ 0 & 1\end{pmatrix}}_{G}\, \theta_{t-1} + w_t, \qquad w_t \;=\; \begin{pmatrix}w_{1,t} \\ w_{2,t}\end{pmatrix} \;\sim\; \mathcal{N}_2\!\left(0,\; W\right),\quad W = \begin{pmatrix}\sigma_{w_1}^2 & 0 \\ 0 & \sigma_{w_2}^2\end{pmatrix}, \]
i.e.\ $w_{1,t}$ and $w_{2,t}$ are \emph{uncorrelated} (no cross-term in $W$).

\emph{Observation equation.}
\[ Y_t \;=\; \mu_t + v_t \;=\; \underbrace{(1,\; 0)}_{F}\, \theta_t + v_t, \qquad v_t \overset{\text{iid}}{\sim} \mathcal{N}(0,\, \sigma^2). \]

All noises $\{w_t\}, \{v_t\}$ and the initial state $\theta_0$ mutually independent.
\end{keydef}

\emph{Notation reminder.} The subscript $i$ in $w_{i,t}$ tells you \emph{which row of the state vector the noise lives in}: $w_{1,t}$ enters the level equation (first state component); $w_{2,t}$ enters the slope equation (second state component). The diagonal entries of $W$ are then $\sigma_{w_1}^2$ (first entry) and $\sigma_{w_2}^2$ (second entry); off-diagonals zero $=$ no correlation between the two noises.

\emph{DLM tuple.}
\[ G = \begin{pmatrix}1 & 1 \\ 0 & 1\end{pmatrix}, \qquad F = (1,\; 0), \qquad W = \mathrm{diag}(\sigma_{w_1}^2,\, \sigma_{w_2}^2), \qquad V = \sigma^2. \]

\textbf{\textcolor{red}{TREND DLMs --- four models, one line of thought.}}

A unified treatment of \emph{Global trend}, \emph{RW + drift}, \emph{Local linear trend (LLT / Local linear growth)}, and \emph{Dynamic linear regression (DLR)}. Each is a relaxation of the previous one: every step lets a previously-fixed quantity become stochastic.

\textbf{\textcolor{red}{The chain of thought.}}

\emph{(1) Simplest possible trend.} A straight line plus noise. Slope and intercept are fixed numbers. \textbf{$\to$ Global trend.}

\emph{(2) But what if the level itself wanders?} Same average direction, but the realised level is a random walk around the line. \textbf{$\to$ RW + drift.}

\emph{(3) What if the slope also wanders?} The "global" trend becomes "local." \textbf{$\to$ LLT / Local linear growth.}

\emph{(4) What if the trend depends on an external variable, not just time?} Replace "time" as predictor with any covariate $x_t$; let coefficients drift. \textbf{$\to$ DLR.}

All four are in the canonical DLM form $\theta_t = G\, \theta_{t-1} + w_t$, $Y_t = F_t\, \theta_t + v_t$, with $w_t \sim \mathcal{N}(0, W)$ and $v_t \sim \mathcal{N}(0, V)$.

\textbf{\textcolor{red}{Side-by-side table --- one model per column.}}

\begin{tabular}{l|l|l|l|l}
& \textbf{Global trend} & \textbf{RW + drift} & \textbf{LLT / Local linear growth} & \textbf{DLR} \\
\hline
\emph{Idea / intuition} & Line $+$ iid noise; parameters fixed. & Drunkard with constant lean: average step $\mu$, staggers around it. Level wanders, drift fixed. & Trend with both wandering level and wandering slope. Captures shifting growth rates. & Regression where the $Y$-vs-$x$ relation evolves. Predictor is an arbitrary covariate, coefficients drift. \\
\hline
\emph{Equations (4-step DLM template)} & \textbf{(1)} $\theta_t = (\mu_0, \delta)^\top \in \mathbb{R}^2$, $\mu_0$ \emph{intercept}, $\delta$ \emph{slope}. \;\textbf{(2)} \emph{Component eq.:} $\mu_0 = \mu_0$, $\delta = \delta$ (frozen, no noise). \;\textbf{(3)} \emph{Matrix state eq.:} $\theta_t = G\theta_{t-1} + w_t = I_2 \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}0 \\ 0\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr)$ (frozen, $G = I_2$, $W = 0$). \emph{Components after multiplication:} $\theta_{t,1} = \mu_0$, $\theta_{t,2} = \delta$. \;\textbf{(4)} \emph{Obs eq.:} $Y_t = F_t\, \theta_t + \varepsilon_t = \mu_0 + \delta t + \varepsilon_t$, $F_t = (1, t)$, $\varepsilon_t \sim \mathcal{N}(0, \sigma^2)$. & \textbf{(1)} $\theta_t \in \mathbb{R}^1$ (scalar level). \;\textbf{(2)} \emph{Component eq.:} $\theta_t = \theta_{t-1} + \mu + w_t$, $w_t \sim \mathcal{N}(0, \sigma_w^2)$. \;\textbf{(3)} \emph{Matrix state eq.:} same as (2) since scalar: $\theta_t = \theta_{t-1} + \mu + w_t$ (= the level itself). $G = 1$, deterministic drift input $\mu$. \;\textbf{(4)} \emph{Obs eq.:} $Y_t = F\, \theta_t + \varepsilon_t = \theta_t + \varepsilon_t$, $F = 1$, $\varepsilon_t \sim \mathcal{N}(0, \sigma^2)$. & \textbf{(1)} $\theta_t = (\mu_t, \beta_t)^\top \in \mathbb{R}^2$, $\mu_t$ \emph{level}, $\beta_t$ \emph{slope}. \;\textbf{(2)} \emph{Component eq.:} $\mu_t = \mu_{t-1} + \beta_{t-1} + w_{1,t}$, $w_{1,t} \sim \mathcal{N}(0, \sigma_{w_1}^2)$; $\beta_t = \beta_{t-1} + w_{2,t}$, $w_{2,t} \sim \mathcal{N}(0, \sigma_{w_2}^2)$. \;\textbf{(3)} \emph{Matrix state eq.:} $\theta_t = G\theta_{t-1} + w_t = \bigl(\begin{smallmatrix}1 & 1 \\ 0 & 1\end{smallmatrix}\bigr)\bigl(\begin{smallmatrix}\mu_{t-1} \\ \beta_{t-1}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}w_{1,t} \\ w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\mu_{t-1} + \beta_{t-1} + w_{1,t} \\ \beta_{t-1} + w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\mu_t \\ \beta_t\end{smallmatrix}\bigr)$, $W = \mathrm{diag}(\sigma_{w_1}^2, \sigma_{w_2}^2)$. \emph{Components after multiplication:} $\mu_t = \mu_{t-1} + \beta_{t-1} + w_{1,t}$ (level absorbs slope $+$ noise); $\beta_t = \beta_{t-1} + w_{2,t}$ (slope is RW). \;\textbf{(4)} \emph{Obs eq.:} $Y_t = F\, \theta_t + \varepsilon_t = \mu_t + \varepsilon_t$, $F = (1, 0)$, $\varepsilon_t \sim \mathcal{N}(0, \sigma^2)$. & \textbf{(1)} $\theta_t = (\alpha_t, \beta_t)^\top \in \mathbb{R}^2$, $\alpha_t$ \emph{intercept}, $\beta_t$ \emph{slope on $x_t$}. \;\textbf{(2)} \emph{Component eq.:} $\alpha_t = \alpha_{t-1} + w_{1,t}$, $w_{1,t} \sim \mathcal{N}(0, \sigma_{w_1}^2)$; $\beta_t = \beta_{t-1} + w_{2,t}$, $w_{2,t} \sim \mathcal{N}(0, \sigma_{w_2}^2)$. \;\textbf{(3)} \emph{Matrix state eq.:} $\theta_t = G\theta_{t-1} + w_t = I_2 \bigl(\begin{smallmatrix}\alpha_{t-1} \\ \beta_{t-1}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}w_{1,t} \\ w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\alpha_{t-1} + w_{1,t} \\ \beta_{t-1} + w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\alpha_t \\ \beta_t\end{smallmatrix}\bigr)$, $W = \mathrm{diag}(\sigma_{w_1}^2, \sigma_{w_2}^2)$. \emph{Components after multiplication:} $\alpha_t = \alpha_{t-1} + w_{1,t}$; $\beta_t = \beta_{t-1} + w_{2,t}$ (independent RWs). \;\textbf{(4)} \emph{Obs eq.:} $Y_t = F_t\, \theta_t + \varepsilon_t = \alpha_t + \beta_t x_t + \varepsilon_t$, $F_t = (1, x_t)$, $\varepsilon_t \sim \mathcal{N}(0, \sigma^2)$. \\
\hline
\emph{Moments / stationarity / forecasts} & $E[Y_t] = \mu_0 + \delta t$;\ \;$\mathrm{Var}(Y_t) = \sigma^2$ (constant); \;forecast bands flat; \;non-stat.\ mean, constant variance. & $E[Y_t] = \theta_0 + t \mu$ (same line); \;$\mathrm{Var}(Y_t) = t \sigma_w^2 + \sigma^2$ (linear); \;forecast bands fan $\propto \sqrt{t}$; \;non-stat.\ mean and variance. & $E[Y_t] = \mu_0 + t \beta_0$ in expectation; \;$\mathrm{Var}(Y_t) \sim t^3$ asymptotic (slope integrates twice); \;forecast bands fan $\propto t^{3/2}$; \;non-stat. & $E[Y_t]$ path-dependent (on $x_{1:t}$); \;$\mathrm{Var}(Y_t)$ depends on the $x$-path; \;forecast bands depend on future $x_t$; \;generally non-stat. \\
\hline
\emph{Nesting / when to use / R} & $=$ DLR with $W = 0, x_t = t$. \;Use when residuals look iid and trend is a clean line. \;R: \verb|lm(y ~ t)|. & $=$ LLT / Local linear growth with $\sigma_{w_2}^2 = 0$. \;Use when there are long swings off the trend line. \;R: \verb|dlmModPoly(1)| with drift input. & $=$ DLR with $x_t = t$. \;Use when the growth rate itself shifts over time. \;R: \verb|dlmModPoly(2)|. & Most general in this family. \;Use when trend depends on an external variable (time-varying betas, marketing mix, clinical covariates). \;R: \verb|dlmModReg(X)|. CAPM case: yt excess return for the asset, xt = excess return for the market \\
\end{tabular}

column 1 and 2 use differet notation but you could write rw + d with a 

In LLT / Local linear growth you put $\beta$ inside $\mu_t$ and use it; in DLR you keep them separate. If I had LLT / Local linear growth-style coupling in DLR it would mean adaptive intercepts.

\textbf{\textcolor{red}{Each model in the other's style (same DLM, two equivalent parametrisations).}}

\emph{RW + drift, written in global-trend style (2D state, slope frozen $=$ LLT / Local linear growth with $\sigma_{w_2}^2 = 0$).}

\emph{State:} $\theta_t = G\, \theta_{t-1} + w_t$ with $\theta_t = (\mu_t,\, \beta_t)^\top$ and $\beta_t \equiv \mu$ frozen, $w_t \sim \mathcal{N}_2(0, W)$, $W = \mathrm{diag}(\sigma_w^2, 0)$, $G = \bigl(\begin{smallmatrix}1 & 1 \\ 0 & 1\end{smallmatrix}\bigr)$. \;\emph{Obs:} $Y_t = F\, \theta_t + \varepsilon_t = \mu_t + \varepsilon_t$ with $\varepsilon_t \sim \mathcal{N}(0, \sigma^2)$, $F = (1,\, 0)$.

\emph{Global trend, written in RW-drift style (scalar evolving state, drift added each step, no noise).}

\emph{State:} $\theta_t = G\, \theta_{t-1} + \delta$ with $\theta_t \in \mathbb{R}$, $W = 0$, $G = 1$, deterministic drift input $\delta$. \;\emph{Obs:} $Y_t = F\, \theta_t + \varepsilon_t = \theta_t + \varepsilon_t$ with $\varepsilon_t \sim \mathcal{N}(0, \sigma^2)$, $F = 1$. \;(Unrolls to $\theta_t = \mu_0 + t\delta$, same line as the original.)

\textbf{\textcolor{red}{Model description}}

\emph{Global trend (Ex 2a).} **Straight line plus noise (OLS). Slope and intercept are fixed numbers** 

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

$\theta = (\underbrace{\mu_0}_{\text{intercept}}, \underbrace{\delta}_{\text{slope}})^\top \in \mathbb{R}^2$, FIXED (deterministic); no $\theta_0$ distribution

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

$\mu_0 = \mu_0$ (constant in $t$); $\delta = \delta$ (constant in $t$); 
\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr) = G\theta_{t-1} + w_t = G \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}0 \\ 0\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}1 & 0 \\ 0 & 1\end{smallmatrix}\bigr)\bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}0 \\ 0\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr)$; joint $w_t \sim \mathcal{N}_2(0, W_t)$ (degenerate point mass at $0$) with $W_t = 0_{2 \times 2}$; $\theta_t \mid \theta_{t-1}$: $\theta_t = \theta_{t-1}$ a.s.\ (degenerate point mass)

\textbf{\textcolor{blue}{(4) Observation eq (final $\to$ generic $\to$ expand $\theta_t$ $\to$ fill $F$ $\to$ result), each $v_{i,t}$, joint $v_t$, $V_t$, $\{v_t\} \perp \{w_s\}, \theta_0$, $Y_t \mid \theta_t$}}

$Y_t = \mu_0 + \delta t + v_t = F_t\theta_t + v_t = F_t \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr) + v_t = (1, t) \bigl(\begin{smallmatrix}\mu_0 \\ \delta\end{smallmatrix}\bigr) + v_t = \mu_0 + \delta t + v_t$; $v_t \sim \mathcal{N}(0, V_t)$, $V_t = \sigma^2$ (scalar); $\{v_t\}$ indep across $t$; $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $Y_t \mid \theta_t \sim \mathcal{N}(\mu_0 + \delta t,\, \sigma^2)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[Y_t] = \mu_0 + \delta t$; $\mathrm{Var}(Y_t) = \sigma^2$ (constant); forecast bands flat; \textbf{non-stat} (linear mean).

\textbf{\textcolor{red}{Model description}}

\emph{RW + drift (Ex 2b).} \emph{(2) But what if the level itself wanders?} Same average direction, but the realised level is a random walk around the line.

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

$\theta_t \in \mathbb{R}$ (\textbf{level}); $\theta_0 \sim \mathcal{N}(m_0, C_0)$

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

$\theta_t = \theta_{t-1} + \mu + w_t$; $w_t \sim \mathcal{N}(0, \sigma_w^2)$ (scalar noise); $\{w_t\}$ indep across $t$ (only one component, no cross-component statement); $\{w_t\} \perp \theta_0$

\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = \theta_t = G\theta_{t-1} + \mu + w_t = 1 \cdot \theta_{t-1} + \mu + w_t = \theta_{t-1} + \mu + w_t$; $w_t \sim \mathcal{N}(0, W_t)$ with $W_t = \sigma_w^2$ (scalar); $\theta_t \mid \theta_{t-1} \sim \mathcal{N}(\theta_{t-1} + \mu,\, \sigma_w^2)$

\textbf{\textcolor{blue}{(4) Observation eq (final $\to$ generic $\to$ expand $\theta_t$ $\to$ fill $F$ $\to$ result), each $v_{i,t}$, joint $v_t$, $V_t$, $\{v_t\} \perp \{w_s\}, \theta_0$, $Y_t \mid \theta_t$}}

$Y_t = \theta_t + v_t = F\theta_t + v_t = 1 \cdot \theta_t + v_t = \theta_t + v_t$; $v_t \sim \mathcal{N}(0, V_t)$, $V_t = \sigma^2$ (scalar); $\{v_t\}$ indep across $t$; $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $Y_t \mid \theta_t \sim \mathcal{N}(\theta_t,\, \sigma^2)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[Y_t] = \theta_0 + t\mu$; $\mathrm{Var}(Y_t) = t\sigma_w^2 + \sigma^2$ (linear in $t$); forecast bands fan $\propto \sqrt{t}$; \textbf{non-stat}. Persistent shocks accumulate via the random walk.

\textbf{\textcolor{red}{Model description}}

\emph{LLT / Local linear growth (Ex 5).} \emph{(3) What if the slope also wanders?} The ``global'' trend becomes ``local.''

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

$\theta_t = (\underbrace{\mu_t}_{\text{level}}, \underbrace{\beta_t}_{\text{slope}})^\top \in \mathbb{R}^2$; $\theta_0 \sim \mathcal{N}_2(m_0, C_0)$

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

$\mu_t = \mu_{t-1} + \beta_{t-1} + w_{1,t}$, $w_{1,t} \sim \mathcal{N}(0, \sigma_{w_1}^2)$, $\{w_{1,t}\}$ indep across $t$; $\beta_t = \beta_{t-1} + w_{2,t}$, $w_{2,t} \sim \mathcal{N}(0, \sigma_{w_2}^2)$, $\{w_{2,t}\}$ indep across $t$; $w_{1,t} \perp w_{2,t}$ (cross-component indep within $t$); $\{w_t\} \perp \theta_0$

\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = \bigl(\begin{smallmatrix}\mu_t \\ \beta_t\end{smallmatrix}\bigr) = G\theta_{t-1} + w_t = G \bigl(\begin{smallmatrix}\mu_{t-1} \\ \beta_{t-1}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}w_{1,t} \\ w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}1 & 1 \\ 0 & 1\end{smallmatrix}\bigr)\bigl(\begin{smallmatrix}\mu_{t-1} \\ \beta_{t-1}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}w_{1,t} \\ w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\mu_{t-1} + \beta_{t-1} + w_{1,t} \\ \beta_{t-1} + w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\mu_t \\ \beta_t\end{smallmatrix}\bigr)$; joint $w_t \sim \mathcal{N}_2(0, W_t)$ with $W_t = \bigl(\begin{smallmatrix}\sigma_{w_1}^2 & 0 \\ 0 & \sigma_{w_2}^2\end{smallmatrix}\bigr)$ (diagonal); $\theta_t \mid \theta_{t-1} \sim \mathcal{N}_2(G\theta_{t-1},\, W_t)$

\textbf{\textcolor{blue}{(4) Observation eq (final $\to$ generic $\to$ expand $\theta_t$ $\to$ fill $F$ $\to$ result), each $v_{i,t}$, joint $v_t$, $V_t$, $\{v_t\} \perp \{w_s\}, \theta_0$, $Y_t \mid \theta_t$}}

$Y_t = \mu_t + v_t = F\theta_t + v_t = F \bigl(\begin{smallmatrix}\mu_t \\ \beta_t\end{smallmatrix}\bigr) + v_t = (1, 0) \bigl(\begin{smallmatrix}\mu_t \\ \beta_t\end{smallmatrix}\bigr) + v_t = \mu_t + v_t$; $v_t \sim \mathcal{N}(0, V_t)$, $V_t = \sigma_v^2$ (scalar); $\{v_t\}$ indep across $t$ (only one component, no cross-component statement); $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $Y_t \mid \theta_t \sim \mathcal{N}(\mu_t,\, \sigma_v^2)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[Y_t] = \mu_0 + t\beta_0$; $\mathrm{Var}(Y_t) \sim t^3$; forecast bands fan $\propto t^{3/2}$; \textbf{non-stat}.

\textbf{\textcolor{red}{Model description}}

\emph{DLR (Ex 7).} \emph{(4) What if the trend depends on an external variable, not just time?} Replace ``time'' with any covariate $x_t$; let coefficients drift.

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

$\theta_t = (\underbrace{\alpha_t}_{\text{intercept}}, \underbrace{\beta_t}_{\text{slope on }x_t})^\top \in \mathbb{R}^2$; $\theta_0 \sim \mathcal{N}_2(m_0, C_0)$

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

$\alpha_t = \alpha_{t-1} + w_{1,t}$, $w_{1,t} \sim \mathcal{N}(0, \sigma_{w_1}^2)$, $\{w_{1,t}\}$ indep across $t$; $\beta_t = \beta_{t-1} + w_{2,t}$, $w_{2,t} \sim \mathcal{N}(0, \sigma_{w_2}^2)$, $\{w_{2,t}\}$ indep across $t$; $w_{1,t} \perp w_{2,t}$ (cross-component indep within $t$); $\{w_t\} \perp \theta_0$

\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = \bigl(\begin{smallmatrix}\alpha_t \\ \beta_t\end{smallmatrix}\bigr) = G\theta_{t-1} + w_t = G \bigl(\begin{smallmatrix}\alpha_{t-1} \\ \beta_{t-1}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}w_{1,t} \\ w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}1 & 0 \\ 0 & 1\end{smallmatrix}\bigr)\bigl(\begin{smallmatrix}\alpha_{t-1} \\ \beta_{t-1}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}w_{1,t} \\ w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\alpha_{t-1} + w_{1,t} \\ \beta_{t-1} + w_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\alpha_t \\ \beta_t\end{smallmatrix}\bigr)$; joint $w_t \sim \mathcal{N}_2(0, W_t)$ with $W_t = \bigl(\begin{smallmatrix}\sigma_{w_1}^2 & 0 \\ 0 & \sigma_{w_2}^2\end{smallmatrix}\bigr)$ (diagonal); $\theta_t \mid \theta_{t-1} \sim \mathcal{N}_2(\theta_{t-1},\, W_t)$

\textbf{\textcolor{blue}{(4) Observation eq (final $\to$ generic $\to$ expand $\theta_t$ $\to$ fill $F$ $\to$ result), each $v_{i,t}$, joint $v_t$, $V_t$, $\{v_t\} \perp \{w_s\}, \theta_0$, $Y_t \mid \theta_t$}}

$Y_t = \alpha_t + \beta_t x_t + v_t = F_t\theta_t + v_t = F_t \bigl(\begin{smallmatrix}\alpha_t \\ \beta_t\end{smallmatrix}\bigr) + v_t = (1, x_t) \bigl(\begin{smallmatrix}\alpha_t \\ \beta_t\end{smallmatrix}\bigr) + v_t = \alpha_t + \beta_t x_t + v_t$; $v_t \sim \mathcal{N}(0, V_t)$, $V_t = \sigma_v^2$ (scalar); $\{v_t\}$ indep across $t$ (only one component, no cross-component statement); $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $Y_t \mid \theta_t \sim \mathcal{N}(\alpha_t + \beta_t x_t,\, \sigma_v^2)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[Y_t]$ path-dep on $x_{1:t}$; $\mathrm{Var}(Y_t)$ depends on $x$-path; \textbf{non-stat}. Most general trend model; CAPM if $x_t$ is market excess return. \emph{Why ``intercept'' (not ``level'')?} $\alpha_t$ is the y-intercept of $Y_t = \alpha_t + \beta_t x_t$ (value at $x_t = 0$); it's a pure RW, no slope integration unlike LLT's level.

\textbf{\textcolor{red}{Model description}}

\emph{Local-level / RW + noise (Ex 1)}

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

$\theta_t \in \mathbb{R}$ (\textbf{hidden level}); $\theta_0 \sim \mathcal{N}(m_0, C_0)$

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

$\theta_t = \theta_{t-1} + w_t$; $w_t \sim \mathcal{N}(0, \sigma_w^2)$ (scalar noise); $\{w_t\}$ indep across $t$ (only one component, no cross-component statement); $\{w_t\} \perp \theta_0$

\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = \theta_t = G\theta_{t-1} + w_t = 1 \cdot \theta_{t-1} + w_t = \theta_{t-1} + w_t$; $w_t \sim \mathcal{N}(0, W_t)$ with $W_t = \sigma_w^2$ (scalar); $\theta_t \mid \theta_{t-1} \sim \mathcal{N}(\theta_{t-1},\, \sigma_w^2)$

