$\mathbf{Y}_t = \bigl(\begin{smallmatrix}X_t \\ Y_t\end{smallmatrix}\bigr) = F_t\theta_t + v_t = F_t \bigl(\begin{smallmatrix}\alpha_t^X \\ \alpha_t^Y \\ \beta_t^X \\ \beta_t^Y\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}v_{1,t} \\ v_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}1 & 0 & x_t & 0 \\ 0 & 1 & 0 & x_t\end{smallmatrix}\bigr)\bigl(\begin{smallmatrix}\alpha_t^X \\ \alpha_t^Y \\ \beta_t^X \\ \beta_t^Y\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}v_{1,t} \\ v_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}\alpha_t^X + \beta_t^X x_t + v_{1,t} \\ \alpha_t^Y + \beta_t^Y x_t + v_{2,t}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}X_t \\ Y_t\end{smallmatrix}\bigr)$ ($F_t = (1, x_t) \otimes I_2$); $v_{1,t} \sim \mathcal{N}(0, \sigma_{v_1}^2)$, $\{v_{1,t}\}$ indep across $t$; $v_{2,t} \sim \mathcal{N}(0, \sigma_{v_2}^2)$, $\{v_{2,t}\}$ indep across $t$; $v_{1,t}, v_{2,t}$ may be correlated within $t$ with $\mathrm{Cov} = \sigma_{v_{12}}$ (Zellner cross-eqn corr.; see $V_t$); joint $v_t \sim \mathcal{N}_2(0, V_t)$ with $V_t = \bigl(\begin{smallmatrix}\sigma_{v_1}^2 & \sigma_{v_{12}} \\ \sigma_{v_{12}} & \sigma_{v_2}^2\end{smallmatrix}\bigr)$; $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $\mathbf{Y}_t \mid \theta_t \sim \mathcal{N}_2(F_t\theta_t,\, V_t)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[\mathbf{Y}_t]^j = m_{\alpha,0}^j + m_{\beta,0}^j x_t$ ($j \in \{X, Y\}$); $\mathrm{Var}$ path-dep on $x_{1:t}$; \textbf{non-stat}. Link in BOTH $W$ (state) and $V$ (obs). CAPM with shared market regressor $x_t$. Petris \S3.3.3.

\textbf{\textcolor{red}{Model description}}

\emph{Superposition (additive components)}

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

stacked: $\theta_t = (\underbrace{\theta_{1,t}^\top}_{\text{comp.\ 1 state}}, \dots, \underbrace{\theta_{k,t}^\top}_{\text{comp.\ }k\text{ state}})^\top \in \mathbb{R}^{p_1 + \cdots + p_k}$; $\theta_0$ stacked from comp.\ priors

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

per component $j = 1, \dots, k$: $\theta_{j,t} = G_j\theta_{j,t-1} + w_{j,t}$, $w_{j,t} \sim \mathcal{N}_{p_j}(0, W_{j,t})$, $\{w_{j,t}\}_t$ indep across $t$; cross-component within $t$: $w_{j,t} \perp w_{l,t}$ for $j \ne l$ (block-diag $W_t$); $\{w_t\} \perp \theta_0$

\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = (\theta_{1,t}^\top, \dots, \theta_{k,t}^\top)^\top = G\theta_{t-1} + w_t = G (\theta_{1,t-1}^\top, \dots, \theta_{k,t-1}^\top)^\top + (w_{1,t}^\top, \dots, w_{k,t}^\top)^\top = \mathrm{blkdiag}(G_1, \dots, G_k) (\theta_{1,t-1}^\top, \dots, \theta_{k,t-1}^\top)^\top + (w_{1,t}^\top, \dots, w_{k,t}^\top)^\top = (G_1\theta_{1,t-1} + w_{1,t},\, \dots,\, G_k\theta_{k,t-1} + w_{k,t})^\top = (\theta_{1,t}^\top, \dots, \theta_{k,t}^\top)^\top$; joint $w_t \sim \mathcal{N}(0, W_t)$ with $W_t = \mathrm{blkdiag}(W_{1,t}, \dots, W_{k,t})$ (block-diag, no cross-component cov.); $\theta_t \mid \theta_{t-1} \sim \mathcal{N}(G\theta_{t-1},\, W_t)$

\textbf{\textcolor{blue}{(4) Observation eq (final $\to$ generic $\to$ expand $\theta_t$ $\to$ fill $F$ $\to$ result), each $v_{i,t}$, joint $v_t$, $V_t$, $\{v_t\} \perp \{w_s\}, \theta_0$, $Y_t \mid \theta_t$}}

$Y_t = \sum_j F_j\theta_{j,t} + v_t = F\theta_t + v_t = [F_1 \mid \dots \mid F_k] (\theta_{1,t}^\top, \dots, \theta_{k,t}^\top)^\top + v_t = \sum_j F_j\theta_{j,t} + v_t$ (row-concat $F$); per component $j$: $v_{j,t} \sim \mathcal{N}(0, V_{j,t})$, $\{v_{j,t}\}_t$ indep across $t$; cross-component within $t$: $v_{j,t} \perp v_{l,t}$ for $j \ne l$; aggregated $v_t = \sum_j v_{j,t} \sim \mathcal{N}(0, V_t)$ with $V_t = \sum_j V_{j,t}$; $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $Y_t \mid \theta_t \sim \mathcal{N}(F\theta_t,\, V_t)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[Y_t] = \sum_j F_j\mathbb{E}[\theta_{j,t}]$; $\mathrm{Var}(Y_t) = V_t + \sum_j F_j\mathrm{Var}(\theta_{j,t})F_j^\top$; stat iff every component is stat. Classic BSM $=$ LLT $+$ seasonal.

\textbf{\textcolor{red}{Model description}}

\emph{Trend + AR(2) cycle (worked above, last row)}

\textbf{\textcolor{blue}{(1) State $\theta_t$, initial $\theta_0$}}

$\theta_t = (\underbrace{T_t}_{\text{trend (RW)}}, \underbrace{C_t}_{\text{cycle (AR(2))}}, \underbrace{C_{t-1}}_{\text{aux lag}})^\top \in \mathbb{R}^3$; $\theta_0 \sim \mathcal{N}_3(m_0, C_0)$

\textbf{\textcolor{blue}{(2) Component equations: each $w_{i,t}$ distribution, $\{w_{i,t}\}$ indep across $t$, cross-component, $\{w_t\} \perp \theta_0$}}

$T_t = T_{t-1} + u_t$, $u_t \sim \mathcal{N}(0, \sigma_T^2)$, $\{u_t\}$ indep across $t$; $C_t = \phi_1 C_{t-1} + \phi_2 C_{t-2} + r_t$, $r_t \sim \mathcal{N}(0, \sigma_C^2)$, $\{r_t\}$ indep across $t$; aux $C_{t-1}$ deterministic copy ($w_{3,t} \equiv 0$, trivially indep across $t$); $u_t \perp r_t$ (cross-component indep within $t$), both indep of the trivial third component; $\{w_t\} \perp \theta_0$

\textbf{\textcolor{blue}{(3) Matrix state eq (final $\to$ generic $\to$ expand $\theta_{t-1}$ $\to$ fill $G$ $\to$ result), joint $w_t$, $W_t$, $\theta_t \mid \theta_{t-1}$}}

$\theta_t = \bigl(\begin{smallmatrix}T_t \\ C_t \\ C_{t-1}\end{smallmatrix}\bigr) = G\theta_{t-1} + w_t = G \bigl(\begin{smallmatrix}T_{t-1} \\ C_{t-1} \\ C_{t-2}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}u_t \\ r_t \\ 0\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}1 & 0 & 0 \\ 0 & \phi_1 & \phi_2 \\ 0 & 1 & 0\end{smallmatrix}\bigr)\bigl(\begin{smallmatrix}T_{t-1} \\ C_{t-1} \\ C_{t-2}\end{smallmatrix}\bigr) + \bigl(\begin{smallmatrix}u_t \\ r_t \\ 0\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}T_{t-1} + u_t \\ \phi_1 C_{t-1} + \phi_2 C_{t-2} + r_t \\ C_{t-1}\end{smallmatrix}\bigr) = \bigl(\begin{smallmatrix}T_t \\ C_t \\ C_{t-1}\end{smallmatrix}\bigr)$; joint $w_t = (u_t, r_t, 0)^\top \sim \mathcal{N}_3(0, W_t)$ with $W_t = \bigl(\begin{smallmatrix}\sigma_T^2 & 0 & 0 \\ 0 & \sigma_C^2 & 0 \\ 0 & 0 & 0\end{smallmatrix}\bigr)$ (singular); $\theta_t \mid \theta_{t-1} \sim \mathcal{N}_3(G\theta_{t-1},\, W_t)$

\textbf{\textcolor{blue}{(4) Observation eq (final $\to$ generic $\to$ expand $\theta_t$ $\to$ fill $F$ $\to$ result), each $v_{i,t}$, joint $v_t$, $V_t$, $\{v_t\} \perp \{w_s\}, \theta_0$, $Y_t \mid \theta_t$}}

$Y_t = T_t + C_t + v_t = F\theta_t + v_t = F \bigl(\begin{smallmatrix}T_t \\ C_t \\ C_{t-1}\end{smallmatrix}\bigr) + v_t = (1, 1, 0) \bigl(\begin{smallmatrix}T_t \\ C_t \\ C_{t-1}\end{smallmatrix}\bigr) + v_t = T_t + C_t + v_t$; $v_t \sim \mathcal{N}(0, V_t)$, $V_t = \sigma_\nu^2$ (scalar); $\{v_t\}$ indep across $t$ (only one component, no cross-component statement); $\{v_t\} \perp \{w_s\}$; $\{v_t\} \perp \theta_0$; $Y_t \mid \theta_t \sim \mathcal{N}(T_t + C_t,\, \sigma_\nu^2)$

\textbf{\textcolor{blue}{(5) Moments, forecasts, stationarity, notes}}

$\mathbb{E}[Y_t] = m_{T,0} + 0$ (if AR(2) cycle stat); $\mathrm{Var}(Y_t) = C_{T,0} + t\sigma_T^2 + \mathrm{Var}(C_t) + \sigma_\nu^2$; \textbf{non-stat} (trend integrates).

\textbf{\textcolor{red}{SUPERPOSITION PRINCIPLE --- additive component DLMs (Petris \S3.2).}}

\emph{Idea.} Build a complex DLM by \emph{adding together} $k$ simpler, mutually independent component DLMs that share one observation. Modular: pick trend + seasonal + AR + regression as bricks, stack their states, and you have a single combined DLM that the Kalman filter handles in one pass.

\textbf{\textcolor{red}{Setup --- $k$ independent component DLMs.}}

For each $j = 1, \dots, k$, component $j$ is its own full DLM (state $+$ obs noise) with state $\theta_{j,t} \in \mathbb{R}^{p_j}$:
\[ \theta_{j,t} = G_j\, \theta_{j,t-1} + w_{j,t}, \quad w_{j,t} \sim \mathcal{N}(0,\, W_j), \qquad Y_{j,t} = F_j\, \theta_{j,t} + v_{j,t}, \quad v_{j,t} \sim \mathcal{N}(0,\, V_j). \]
All shocks independent across components AND across time: $w_{j,t} \perp\!\!\!\perp w_{l,t}$, $v_{j,t} \perp\!\!\!\perp v_{l,t}$ for $j \ne l$, and $\theta_{j,0}$'s independent.

\emph{Observation as a sum.}
\[ Y_t \;=\; Y_{1,t} + Y_{2,t} + \cdots + Y_{k,t} \;=\; \sum_{j=1}^k F_j\, \theta_{j,t} \;+\; \underbrace{\sum_{j=1}^k v_{j,t}}_{v_t \,\sim\, \mathcal{N}(0,\, V),\; V \,=\, \sum_j V_j}. \]
\emph{Why one combined $v_t$?} The component noises $v_{j,t}$ are independent Gaussians, so their sum is Gaussian with variance $V = \sum_j V_j$. From the observed-side perspective, ``one obs noise per component'' and ``one combined obs noise $V$'' are \emph{indistinguishable} --- but the per-component split is useful for bookkeeping when each brick has its own well-understood noise scale (e.g., trend-irregular vs.\ measurement error).

\textbf{\textcolor{red}{Combine --- 4-step DLM template.}}

\emph{(1) State (stack components).}
\[ \theta_t \;=\; \begin{pmatrix} \theta_{1,t} \\ \theta_{2,t} \\ \vdots \\ \theta_{k,t} \end{pmatrix} \;\in\; \mathbb{R}^{p_1 + \cdots + p_k}. \]
each $\theta_{j,t}$ can be any dimension $p_j \geq 1$

\emph{(2) Component equations.} Already given above --- each $\theta_{j,t}$ evolves on its own with $G_j, W_j$.

\emph{(3) Matrix state equation (block-diagonal $G$ and $W$).}
\[ \theta_t = G\, \theta_{t-1} + w_t, \qquad w_t \overset{\mathrm{iid}}{\sim} \mathcal{N}(0,\, W_t), \qquad G = \mathrm{blkdiag}(G_1, \dots, G_k), \qquad W_t = \mathrm{blkdiag}(W_1, \dots, W_k). \]
The block-diagonal structure encodes ``no cross-coupling between components.''

\emph{(4) Observation equation (row-concatenate the $F$'s; sum the obs noises).}
\[ Y_t = F\, \theta_t + v_t, \qquad v_t \overset{\mathrm{iid}}{\sim} \mathcal{N}(0,\, V_t), \qquad F = [\,F_1 \;\big|\; F_2 \;\big|\; \cdots \;\big|\; F_k\,], \qquad V_t = \sum_{j=1}^k V_j. \]
\emph{Distributional form.} $\theta_t \mid \theta_{t-1} \sim \mathcal{N}\bigl(G\theta_{t-1},\, W\bigr)$; $\;Y_t \mid \theta_t \sim \mathcal{N}\bigl(F\theta_t,\, V\bigr)$ with $V = \sum_j V_j$.

\textbf{\textcolor{red}{Why it works (intuition).}}

$\bullet$ \emph{Gaussian closure.} A sum of independent Gaussians is Gaussian. So $\sum_j F_j \theta_{j,t}$ is Gaussian, and adding $v_t$ keeps it Gaussian.

$\bullet$ \emph{Independence preserved by stacking.} Block-diagonal $G, W$ means the components NEVER mix in mean or in shocks --- they evolve in parallel. The Kalman recursion on the combined state effectively runs $k$ parallel recursions for the conditional means, with the \emph{only} cross-talk happening through the joint update against the observation $y_t$ (which sees the sum).

$\bullet$ \emph{Modularity.} You design each brick once (LLT, seasonal, AR, regression on $x_t$) and reuse them in any combination.

\textbf{\textcolor{red}{Canonical example --- Basic Structural Model (BSM).}}

\[ Y_t = \underbrace{\mu_t}_{\text{trend (LLT)}} + \underbrace{\gamma_t}_{\text{seasonal}} + \underbrace{v_t}_{\text{irregular}}. \]

\emph{Trend brick (LLT, $p_1 = 2$):} $\theta_{1,t} = (\mu_t, \beta_t)$, $G_1 = \bigl(\begin{smallmatrix}1 & 1 \\ 0 & 1\end{smallmatrix}\bigr)$, $F_1 = (1,\, 0)$.

\emph{Quarterly seasonal brick ($p_2 = 3$):} $\theta_{2,t} = (\gamma_t,\, \gamma_{t-1},\, \gamma_{t-2})$, $G_2 = \bigl(\begin{smallmatrix}-1 & -1 & -1 \\ 1 & 0 & 0 \\ 0 & 1 & 0\end{smallmatrix}\bigr)$, $F_2 = (1, 0, 0)$.

\emph{Combined.} State $\theta_t \in \mathbb{R}^5$ (2 trend $+$ 3 seasonal), $G = \mathrm{blkdiag}(G_1, G_2)$, $F = [\,1\;0\;1\;0\;0\,]$. One DLM; one Kalman filter pass; outputs both the trend $\mu_t$ and the seasonal $\gamma_t$ separately as components of the filtered state.

\textbf{\textcolor{red}{More compositions (same recipe).}}

$\bullet$ \emph{LLT + AR(1) cycle:} trend $+$ a stationary AR(1) for short-run fluctuations. State $\in \mathbb{R}^3$.

$\bullet$ \emph{LLT + regression on $x_t$:} trend $+$ DLR with time-varying $(\alpha_t, \beta_t)$. State $\in \mathbb{R}^4$. ``Trend plus covariate response.''

$\bullet$ \emph{Trend + seasonal + regression:} the classic Holt-Winters in DLM clothing.
